45	enum Network ParseNetwork(const std::string& net_in) {
46	    std::string net = ToLower(net_in);
47	    if (net == "ipv4") return NET_IPV4;
48	    if (net == "ipv6") return NET_IPV6;
49	    if (net == "onion") return NET_ONION;
50	    if (net == "tor") {
51	        LogPrintf("Warning: net name 'tor' is deprecated and will be removed in the future. You should use 'onion' instead.\n");
52	        return NET_ONION;
53	    }
54	    if (net == "i2p") {
55	        return NET_I2P;
56	    }
57	    return NET_UNROUTABLE;
58	}
