76	std::vector<std::string> GetNetworkNames(bool append_unroutable)
77	{
78	    std::vector<std::string> names;
79	    for (int n = 0; n < NET_MAX; ++n) {
80	        const enum Network network{static_cast<Network>(n)};
81	        if (network == NET_UNROUTABLE || network == NET_CJDNS || network == NET_INTERNAL) continue;
82	        names.emplace_back(GetNetworkName(network));
83	    }
84	    if (append_unroutable) {
85	        names.emplace_back(GetNetworkName(NET_UNROUTABLE));
86	    }
87	    return names;
88	}
