163	/**
164	 * Resolve a host string to its corresponding network addresses.
165	 *
166	 * @param name    The string representing a host. Could be a name or a numerical
167	 *                IP address (IPv6 addresses in their bracketed form are
168	 *                allowed).
169	 * @param[out] vIP The resulting network addresses to which the specified host
170	 *                 string resolved.
171	 *
172	 * @returns Whether or not the specified host string successfully resolved to
173	 *          any resulting network addresses.
174	 *
175	 * @see Lookup(const char *, std::vector<CService>&, int, bool, unsigned int)
176	 *      for additional parameter descriptions.
177	 */
178	bool LookupHost(const std::string& name, std::vector<CNetAddr>& vIP, unsigned int nMaxSolutions, bool fAllowLookup)
179	{
180	    if (!ValidAsCString(name)) {
181	        return false;
182	    }
183	    std::string strHost = name;
184	    if (strHost.empty())
185	        return false;
186	    if (strHost.front() == '[' && strHost.back() == ']') {
187	        strHost = strHost.substr(1, strHost.size() - 2);
188	    }
189	
190	    return LookupIntern(strHost, vIP, nMaxSolutions, fAllowLookup);
191	}
